<parameter name="content">import { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary]", error.message, {
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  retry = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.retry);

    return (
      <div role="alert" style={{ padding: "1.5rem", fontFamily: "sans-serif" }}>
        <h2 style={{ margin: "0 0 0.5rem" }}>Something went wrong</h2>
        <pre
          style={{
            background: "#f4f4f4",
            padding: "0.75rem",
            borderRadius: "4px",
            fontSize: "0.85rem",
            overflowX: "auto",
          }}
        >
          {error.message}
        </pre>
        <button
          onClick={this.retry}
          style={{
            marginTop: "1rem",
            padding: "0.5rem 1.25rem",
            cursor: "pointer",
            borderRadius: "4px",
            border: "1px solid #ccc",
          }}
        >
          Retry
        </button>
      </div>
    );
  }
}
